CASES=[
('בג"ץ 1/49 בז\'רנו נ\' שר המשטרה','עובדות: מתווכים טיפלו עבור בעלי רכב ברישיונות ובטסטים במשרד הרישוי. בעקבות תלונות על הנחות ועקיפת תורים הורה שר המשטרה שרק בעלי הרכב יורשו להיכנס. המתווכים, שפרנסתם נפגעה, עתרו.','הלכה: העתירה התקבלה. לרשות מותר לעשות רק מה שהחוק הסמיך אותה, ופגיעה בחופש העיסוק מחייבת הסמכה מפורשת. גם רשות מוסמכת צריכה לפרש את סמכותה כך שתימנע פגיעה בזכויות, ועל הפקיד להוכיח צידוק לאיסור. חשיבות למבחן: פסק הדין המכונן של חוקיות המנהל, ונקודת מוצא לכל שאלת סמכות.'),
('בג"ץ 144/50 שייב נ\' שר הביטחון','עובדות: ישראל שייב, מראשי הלח"י, ביקש לעבוד כמורה. שר הביטחון, שהיה גם ראש הממשלה, התנגד בשל דבריו נגד צה"ל.','הלכה: העתירה התקבלה. לשר הביטחון אין סמכות להורות בעניין העסקת מורים, ולכן ההחלטה בטלה מכל טעם. דרישת הסמכות חלה גם על הדרג הבכיר ביותר, ובית המשפט לא נרתע מלהכריע נגדו. חשיבות למבחן: חוקיות המנהל מול בעל סמכות בכיר, ובנוסף עצמאות שיקול הדעת (פרק 6).'),
('ע"ב 1/65 ירדור נ\' ועדת הבחירות; ע"ב 2/84 ניימן נ\' יו"ר ועדת הבחירות','עובדות: ועדת הבחירות פסלה רשימות לכנסת בלי הסמכה מפורשת בחוק לפסילה מטעמים כאלה.','הלכה: בירדור אושרה הפסילה, בנימוק של "דמוקרטיה מתגוננת" – חריג שבו עקרונות יסוד של השיטה גוברים על חוקיות המנהל. בניימן נקבע שאין סמכות לפסול את הרשימות, שירדור צומצמה לנסיבותיה, ולאחר מכן תוקן החוק. חשיבות למבחן: החריג הנדיר וגבולותיו.'),
('עתירת רופאים לזכויות אדם נ\' השר לביטחון פנים','עובדות: בתחילת מבצע החיסונים לקורונה קבע שר הבריאות שאסירים וסוהרים יחוסנו בעדיפות. השר לביטחון פנים הורה לשב"ס שלא לחסן אסירים עד לאישורו.','הלכה: ההנחיה ניתנה בחוסר סמכות מובהק ובניגוד לדין, וממילא נעדרת תוקף משפטי; הסמכות לפי פקודת בריאות העם נתונה לגורם אחר. חשיבות למבחן: יישום עכשווי של חוקיות המנהל כשגורם מבצעי נוטל סמכות שאינה שלו.'),
('בג"ץ 262/62 פרץ נ\' המועצה המקומית כפר שמריהו','עובדות: המועצה סירבה להשכיר אולם בבעלותה לקהילה רפורמית לצורכי תפילה.','הלכה: העתירה התקבלה. הרשות נטלה על עצמה תפקיד של נאמן כלפי הציבור והיא חייבת להתייחס יחס שווה אל שווים. חשיבות למבחן: מקור עקרון השוויון, ופסק הדין הראשון המדגים את חובת הנאמנות.'),
('בג"ץ 164/97 קונטרם נ\' משרד האוצר – אגף המכס','עובדות: חברה קיבלה רישיון מחסן ערובה על סמך מסמך מטעה, והרישיון נשלל. החברה עתרה.','הלכה: העתירה נדחתה. זמיר: חובת הגינות כללית של הפרט כלפי הרשות. ברק: חובת גילוי הנגזרת מצורך הרשות בתשתית עובדתית כשהמידע בידי הפרט. חשין: רק אם נקבע בחוק. מכל העמדות עולה שהפרט חייב לגלות מידע מהותי. חשיבות למבחן: הצד השני של הנאמנות, ושלוש העמדות.'),
('בג"ץ 7081/93 בוצר נ\' המועצה המקומית מכבים-רעות','עובדות: תלמיד עם מוגבלות ביקש הנגשת בית הספר. הרשות טענה לאילוצי תקציב ולקשיים בירוקרטיים.','הלכה: הרשות חייבת לאזן בין שיקולי תקציב לבין זכויות, ואינה יכולה להסתתר מאחורי הבירוקרטיה; היא חויבה לפעול. חשיבות למבחן: רשות מאזנת כנאמן, וקשר בין נאמנות לזכויות יסוד.'),
]
